// Regrouper le scénario d'ajout au panier depuis la page Inventory.
describe('Swag Labs inventory cart', () => {
  // Se connecter avant le scénario avec la commande partagée.
  beforeEach(() => {
    // Ouvrir une session utilisateur standard sur Inventory.
    cy.login();
  });

  // Fermer la session après le scénario avec la commande partagée.
  afterEach(() => {
    // Déconnecter l'utilisateur après la vérification.
    cy.logout();
  });

  // Définir le scénario d'ajout d'un produit depuis la liste Inventory.
  it('ajoute le Sauce Labs Backpack au panier depuis Inventory', () => {
    // Vérifier que la page Inventory est affichée.
    cy.get('[data-test="title"]').should('be.visible').and('have.text', 'Products');

    // Ajouter le Sauce Labs Backpack depuis la liste des produits.
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Vérifier que le bouton indique que le produit peut être retiré du panier.
    cy.get('[data-test="remove-sauce-labs-backpack"]').should('be.visible').and('have.text', 'Remove');
    // Vérifier que le badge du panier indique un produit.
    cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '1');
  });
});
